/** Travel-document (ICAO) codes that are not ISO alpha-3, to the country that issues them. */
const ICAO: Record<string, string> = {
  D: 'DE',
  GBD: 'GB',
  GBN: 'GB',
  GBO: 'GB',
  GBP: 'GB',
  GBS: 'GB',
  RKS: 'XK',
};

const A2 = new Set(ISO.map((r) => r[0]));
const FROM_A3 = new Map(ISO.map((r) => [r[1], r[0]]));
const FROM_NAME = new Map(ISO.map((r) => [r[2].toLowerCase(), r[0]]));

/** An alpha-2, alpha-3, travel-document code or country name, as ISO alpha-2 (upper case); undefined when it is none of them. */
export function country2(v: unknown): string | undefined {
  if (typeof v !== 'string') return undefined;
  const s = v.trim().replace(/<+$/, '');
  if (!s) return undefined;
  const up = s.toUpperCase();
  if (up.length === 2 && A2.has(up)) return up;
  return FROM_A3.get(up) ?? ICAO[up] ?? FROM_NAME.get(s.toLowerCase());
}

const NAME_OF = new Map(ISO.map((r) => [r[0], r[2]]));

/** The common English name for an ISO alpha-2 code ("NA" -> "Namibia"); undefined when it is not a known code. */
export function countryName(a2: unknown): string | undefined {
  return typeof a2 === 'string' ? NAME_OF.get(a2.toUpperCase()) : undefined;
}
